FROM golang:{{go_version}}-alpine AS build
WORKDIR /src
COPY go.mod go.sum ./
RUN go mod download
COPY . .
RUN CGO_ENABLED=0 GOOS=linux go build -ldflags="-s -w" -o /out/{{binary_name}} ./cmd/{{binary_name}}

FROM gcr.io/distroless/static-debian12
COPY --from=build /out/{{binary_name}} /{{binary_name}}
EXPOSE {{port}}
ENTRYPOINT ["/{{binary_name}}"]
